arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_df43a08a54ac4ca7b28e24334762894c.Models
@using sv_df43a08a54ac4ca7b28e24334762894c.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (_submitted)
    {
        <div class="alert alert-success text-center py-5">
            <h3>🎉 Application Submitted!</h3>
            <p class="lead mt-3">Your application has been received.</p>
            <p>Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       StepLabels="_stepLabels"
                       OnStepClicked="GoToStep" />

        <div class="card mt-4">
            <div class="card-body">
                @if (_currentStep == 0)
                {
                    <PersonalInfoStep @ref="_personalInfoStep"
                                      FullName="@_fullName"
                                      Email="@_email"
                                      Phone="@_phone"
                                      Address="@_address"
                                      OnFullNameChanged="v => _fullName = v"
                                      OnEmailChanged="v => _email = v"
                                      OnPhoneChanged="v => _phone = v"
                                      OnAddressChanged="v => _address = v" />
                }
                else if (_currentStep == 1)
                {
                    <WorkHistoryStep @ref="_workHistoryStep"
                                     Entries="_workEntries" />
                }
                else if (_currentStep == 2)
                {
                    <ReferencesStep @ref="_referencesStep"
                                    References="_references" />
                }
                else if (_currentStep == 3)
                {
                    <CoverLetterStep CoverLetter="@_coverLetter"
                                     OnCoverLetterChanged="v => _coverLetter = v"
                                     MaxLength="2000" />
                }
                else if (_currentStep == 4)
                {
                    <ReviewStep FullName="@_fullName"
                                Email="@_email"
                                Phone="@_phone"
                                Address="@_address"
                                WorkEntries="_workEntries"
                                References="_references"
                                CoverLetter="@_coverLetter"
                                OnEditSection="GoToStep" />
                }
            </div>
