{"file_text": "<div class="d-flex justify-content-between align-items-center mb-2">
    @for (int i = 0; i < StepLabels.Length; i++)
    {
        var step = i;
        var isCurrent = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var isClickable = isCompleted && !isCurrent;

        <div class="text-center flex-fill position-relative">
            <div class="d-flex align-items-center justify-content-center mb-1">
                @if (step > 0)
                {
                    <div class="flex-grow-1" style="height: 2px; background: @(isCompleted || isCurrent ? "#0d6efd" : "#dee2e6");"></div>
                }
                <div @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(step); }"
                     class="rounded-circle d-flex align-items-center justify-content-center @(isClickable ? "cursor-pointer" : "")"
                     style="width: 36px; height: 36px; min-width: 36px; font-size: 0.85rem; font-weight: 600;
                            background: @(isCurrent ? "#0d6efd" : isCompleted ? "#198754" : "#dee2e6");
                            color: @(isCurrent || isCompleted ? "white" : "#6c757d");
                            cursor: @(isClickable ? "pointer" : "default");
                            transition: all 0.2s;">
                    @if (isCompleted && !isCurrent)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                @if (step < StepLabels.Length - 1)
                {
                    <div class="flex-grow-1" style="height: 2px; background: @(isCompleted ? "#0d6efd" : "#dee2e6");"></div>
                }
            </div>
            <small class="@(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")"
                   style="font-size: 0.75rem; cursor: @(isClickable ? "pointer" : "default");"
                   @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(step); }">
                @StepLabels[step]
            </small>
        </div>
    }
</div>

